    private void tune(LiveTvData.Channel next){if(closed)return;if(controls!=null)controls.close();timeShiftStatus=TvInputManager.TIME_SHIFT_STATUS_UNSUPPORTED;paused=false;shiftStart=shiftCurrent=0;channel=next;historyNotified=false;VelaWorkspace.prefs(getContext(),"lite_tv").edit().putString("selected",next.identity).putString("selected_alias",next.alias).apply();ready=false;failed=false;blocked=false;quality="";programmes=Collections.emptyMap();main.removeCallbacks(timeout);main.removeCallbacks(hideInfo);main.removeCallbacks(hideBadge);message.setText(t("Tuning…","Sintonizando…"));message.setVisibility(VISIBLE);badge.setText(t("LIVE","DIRECTO"));badge.setVisibility(VISIBLE);showInfo();load();try{television.setStreamVolume(1f);television.tune(channel.inputId,TvContract.buildChannelUri(channel.providerId));main.postDelayed(timeout,25000);}catch(RuntimeException unavailable){failure(t("Playback is unavailable on this television.","La reproducción no está disponible en esta televisión."));}}
