    private void drawPicker(Map<String,Bitmap> artwork){String signature=pickerPage+":"+pickerFavorites+":"+pickerRecent;for(int i=pickerPage*6;i<Math.min(pickerValues.size(),pickerPage*6+6);i++){LiveTvData.Channel item=pickerValues.get(i);signature+=":"+item.id+":"+favourites.has(item,allChannels)+":"+item.id.equals(channel.id);}if(signature.equals(pickerSignature)&&picker.getChildCount()>0){updatePickerRows(artwork);return;}String focused="",tab="";int oldRow=0;View before=picker.findFocus();if(!pickerFocusRows&&before!=null&&before.getTag() instanceof String&&((String)before.getTag()).startsWith("@"))tab=(String)before.getTag();for(int i=0;i<pickerRows.size();i++)if(pickerRows.get(i).hasFocus()){focused=(String)pickerRows.get(i).getTag();oldRow=i;}clearPicker();pickerSignature=signature;Context c=getContext();put(picker,text(c,t("Channels","Canales"),30,VelaTheme.WHITE),32,26,280,48);TextView last=button(c,t("Previous channel","Canal anterior"),()->{closePicker();previousChannel();});put(picker,last,322,26,318,48);TextView listTab=button(c,(pickerFavorites||pickerRecent?"":"✓ ")+t("List","Lista"),()->filterPicker(false)),favTab=button(c,(pickerFavorites?"✓ ":"")+"★ "+t("Favourites","Favoritos"),()->filterPicker(true));listTab.setTag("@list");favTab.setTag("@favorites");put(picker,listTab,32,86,188,50);put(picker,favTab,230,86,200,50);TextView recentTab=button(c,(pickerRecent?"✓ ":"")+t("Recent","Recientes"),()->{pickerRecent=true;pickerFavorites=false;refreshPicker();});recentTab.setTag("@recent");put(picker,recentTab,440,86,200,50);for(TextView tabView:new TextView[]{listTab,favTab,recentTab}){boolean selectedTab=tabView==listTab?!pickerFavorites&&!pickerRecent:tabView==favTab?pickerFavorites:pickerRecent;VelaPlayerUi.tab(tabView,selectedTab);tabView.setOnFocusChangeListener((v,f)->VelaPlayerUi.tab(tabView,selectedTab));}put(picker,text(c,t("OK · Watch    Hold OK ★    Back · Close","OK · Ver    Mantener OK ★    Atrás · Cerrar"),17,VelaTheme.MUTED),32,950,622,34);View target=null;long now=System.currentTimeMillis()/1000;
        for(int i=pickerPage*6;i<Math.min(pickerValues.size(),pickerPage*6+6);i++){LiveTvData.Channel item=pickerValues.get(i);int row=i-pickerPage*6;FrameLayout card=new FrameLayout(c);card.setFocusable(true);card.setFocusableInTouchMode(true);card.setDefaultFocusHighlightEnabled(false);card.setTag(item.id);card.setBackground(VelaPlayerUi.row(c,false,item.id.equals(channel.id)));Logo logo=new Logo(c,item);logo.plated();logo.bitmap(artwork.get(item.id));put(card,logo,14,22,72,72);logoViews.add(logo);TextView name=text(c,(favourites.has(item,allChannels)?"★ ":"")+item.name,22,VelaTheme.WHITE);name.setTag("name");put(card,name,112,10,432,34);TextView state=text(c,item.id.equals(channel.id)?"●":"",18,VelaTheme.WHITE);state.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);put(card,state,564,10,44,34);LiveTvData.Programme p=current(programmes,item,now);TextView show=text(c,p==null?t("No programme information","Sin programación"):p.title,19,VelaTheme.SECONDARY);show.setTag("show");put(card,show,112,49,474,29);TextView left=text(c,p==null?"":LiveTvActivity.remainingText(p.remainingMinutes(now)),17,VelaTheme.SECONDARY);left.setTag("left");put(card,left,112,85,474,27);Progress bar=new Progress(c);bar.setTag("progress");bar.value(p==null?0:p.progress(now));put(card,bar,112,112,474,4);put(picker,card,24,160+row*128,648,120);pickerRows.add(card);card.setContentDescription((item.id.equals(channel.id)?L10n.text("Watching")+" · ":"")+name.getText()+" · "+show.getText()+" · "+left.getText());card.setOnFocusChangeListener((v,f)->{card.setBackground(VelaPlayerUi.row(c,f,item.id.equals(channel.id)));bar.onLight(f);state.setTextColor(f?VelaTheme.INK:VelaTheme.WHITE);name.setTextColor(f?VelaTheme.INK:VelaTheme.WHITE);show.setTextColor(f?0xFF626773:VelaTheme.SECONDARY);left.setTextColor(f?0xFF626773:VelaTheme.SECONDARY);});card.setOnClickListener(v->{closePicker();if(!item.id.equals(channel.id))tune(item);});card.setOnLongClickListener(v->{channelOptions(item);return true;});TvRemotePress press=new TvRemotePress(card,card::performClick,card::performLongClick);card.setOnKeyListener((v,k,e)->{if(press.key(e))return true;if(e.getAction()!=0)return false;if(k==KeyEvent.KEYCODE_DPAD_UP&&row==0&&pickerPage>0){pickerPage--;drawPicker(Collections.emptyMap());pickerRows.get(pickerRows.size()-1).requestFocus();load();return true;}if(k==KeyEvent.KEYCODE_DPAD_DOWN&&row==5&&(pickerPage+1)*6<pickerValues.size()){pickerPage++;drawPicker(Collections.emptyMap());pickerRows.get(0).requestFocus();load();return true;}if(k==KeyEvent.KEYCODE_DPAD_LEFT){closePicker();return true;}return false;});if(item.id.equals(focused)||focused.isEmpty()&&item.id.equals(channel.id))target=card;}
        TextView count=text(c,pickerValues.isEmpty()?t("No favourites yet","Aún no tienes favoritos"):(pickerPage*6+1)+"–"+Math.min(pickerValues.size(),pickerPage*6+6)+" / "+pickerValues.size(),17,VelaTheme.MUTED);put(picker,count,32,1000,610,26);if(target==null&&!pickerRows.isEmpty())target=pickerRows.get(Math.min(oldRow,pickerRows.size()-1));if(tab.equals("@list"))listTab.requestFocus();else if(tab.equals("@favorites"))favTab.requestFocus();else if(tab.equals("@recent"))recentTab.requestFocus();else if(target!=null)target.requestFocus();else (pickerRecent?recentTab:favTab).requestFocus();}
    private void updatePickerRows(Map<String,Bitmap> artwork){long now=System.currentTimeMillis()/1000;for(int i=0;i<pickerRows.size();i++){View row=pickerRows.get(i);LiveTvData.Channel item=pickerValues.get(pickerPage*6+i);LiveTvData.Programme p=current(programmes,item,now);((TextView)row.findViewWithTag("show")).setText(p==null?t("No programme information","Sin programación"):p.title);((TextView)row.findViewWithTag("left")).setText(p==null?"":LiveTvActivity.remainingText(p.remainingMinutes(now)));((Progress)row.findViewWithTag("progress")).value(p==null?0:p.progress(now));if(artwork.containsKey(item.id))((Logo)((FrameLayout)row).getChildAt(0)).bitmap(artwork.get(item.id));}}
    private List<LiveTvData.Channel> pickerValues(){if(pickerRecent)return LiteChannelPersonal.recent(getContext(),allChannels);if(!pickerFavorites)return channels;List<LiveTvData.Channel> list=new ArrayList<>();for(LiveTvData.Channel c:channels)if(favourites.has(c,allChannels))list.add(c);LiteChannelPersonal.sort(getContext(),list,allChannels);return list;}
    private void filterPicker(boolean value){if(pickerFavorites==value&&!pickerRecent)return;pickerRecent=false;pickerFavorites=value;pickerValues=pickerValues();pickerPage=Math.max(0,pickerValues.indexOf(channel))/6;pickerFocusRows=true;drawPicker(Collections.emptyMap());pickerFocusRows=false;load();}
    private void refreshPicker(){pickerValues=pickerValues();pickerPage=Math.max(0,pickerValues.indexOf(channel))/6;pickerFocusRows=true;drawPicker(Collections.emptyMap());pickerFocusRows=false;load();}
    private void previousChannel(){for(LiveTvData.Channel c:LiteChannelPersonal.recent(getContext(),allChannels))if(!c.id.equals(channel.id)){tune(c);return;}Toast.makeText(getContext(),t("No previous channel","No hay canal anterior"),Toast.LENGTH_SHORT).show();}
    private void toggleFavorite(LiveTvData.Channel item){favourites.toggle(item,allChannels);Toast.makeText(getContext(),favourites.has(item,allChannels)?t("Added to favourites","Añadido a favoritos"):t("Removed from favourites","Quitado de favoritos"),Toast.LENGTH_SHORT).show();if(pickerShown){pickerValues=pickerValues();pickerPage=Math.min(pickerPage,Math.max(0,(pickerValues.size()-1)/6));drawPicker(Collections.emptyMap());}load();}
    private void dismissInfo(){infoShown=false;main.removeCallbacks(hideInfo);info.setVisibility(GONE);}
    private void selectClick(){if(blocked)host.nativeTv(channel);else if(failed)tune(channel);else if(infoShown){infoShown=false;main.removeCallbacks(hideInfo);info.setVisibility(GONE);}else showInfo();}
    boolean remote(KeyEvent e){int key=e.getKeyCode();if(key==controlsKey){if(e.getAction()==KeyEvent.ACTION_UP)controlsKey=-1;return true;}if(controls!=null)return controls.remote(e);if(key==KeyEvent.KEYCODE_MENU){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)openControls();return true;}if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE&&timeShiftStatus==TvInputManager.TIME_SHIFT_STATUS_AVAILABLE){if(e.getAction()==0){if(paused)television.timeShiftResume();else television.timeShiftPause();paused=!paused;}return true;}if(pickerShown){if(key==KeyEvent.KEYCODE_BACK&&e.getAction()==KeyEvent.ACTION_UP){closePicker();return true;}return key==KeyEvent.KEYCODE_BACK;}
        if(selectPress.key(e))return true;
        if(key==KeyEvent.KEYCODE_BACK){if(e.getAction()==KeyEvent.ACTION_UP){if(infoShown&&ready&&!failed&&!blocked)dismissInfo();else host.exit();}return true;}
        if(e.getAction()==KeyEvent.ACTION_DOWN){if(key==KeyEvent.KEYCODE_DPAD_RIGHT){openPicker();return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){openPicker();int index=pickerValues.indexOf(channel)+(key==KeyEvent.KEYCODE_DPAD_UP?-1:1);if(index>=0&&index<pickerValues.size()){pickerPage=index/6;drawPicker(Collections.emptyMap());for(View row:pickerRows)if(pickerValues.get(index).id.equals(row.getTag()))row.requestFocus();load();}return true;}if(key==KeyEvent.KEYCODE_LAST_CHANNEL){if(e.getRepeatCount()==0)previousChannel();return true;}if(key==KeyEvent.KEYCODE_CHANNEL_UP||key==KeyEvent.KEYCODE_CHANNEL_DOWN){if(e.getRepeatCount()==0){int direction=key==KeyEvent.KEYCODE_CHANNEL_UP?1:-1,index=channels.indexOf(channel),next=(index+direction+channels.size())%channels.size();tune(channels.get(next));}return true;}if(key==KeyEvent.KEYCODE_DPAD_LEFT){if(e.getRepeatCount()==0){if(infoShown){controlsKey=key;openControls();}else showInfo();}return true;}}return key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_CHANNEL_UP||key==KeyEvent.KEYCODE_CHANNEL_DOWN||key==KeyEvent.KEYCODE_LAST_CHANNEL;
    }
    public void close(){sleep.close();if(controls!=null)controls.close();selectPress.cancel();if(closed)return;closed=true;generation++;main.removeCallbacksAndMessages(null);if(cancellation!=null)cancellation.cancel();if(job!=null)job.cancel(true);worker.shutdownNow();television.setCallback(null);television.reset();for(Logo v:logoViews)v.clear();logoViews.clear();logos.close();programmes=Collections.emptyMap();channels.clear();allChannels.clear();removeAllViews();}
